<p><a class="btn btn-dark btn-sm" href="<?= e(url('admin/blog/new')) ?>">+ New post</a></p><table class="data-table"><tr><th>Title</th><th>Status</th><th>Date</th><th></th></tr><?php foreach ($items as $p): ?><tr><td><?= e($p['title']) ?></td><td><?= $p['is_published'] ? 'Published' : 'Draft' ?></td><td><?= e(time_ago($p['created_at'])) ?></td><td><a href="<?= e(url('admin/blog/' . $p['id'] . '/edit')) ?>">Edit</a> &middot; <form method="post" style="display:inline" action="<?= e(url('admin/blog/' . $p['id'] . '/delete')) ?>" data-confirm="Delete?"><?= csrf_field() ?><button class="link">Delete</button></form></td></tr><?php endforeach; ?></table>
